async (page) => {
  const email = `explore-${Date.now()}@example.test`;
  const pw = 'Passw0rd!explore';
  const snap = async (label) => { await page.waitForTimeout(900); return `### ${label} ${page.url()}\n` + (await page.locator('mat-sidenav-content, body').last().ariaSnapshot()).split('\n').filter(l => !/Sidenav|homepage|OWASP Juice Shop|Open search|Close search|textbox\n|Account|Your Basket|Language|Show\/hide/.test(l)).join('\n'); };
  const out = [];
  await page.goto('http://localhost:3000/#/register');
  await page.getByRole('textbox', { name: 'Email address field' }).fill(email);
  await page.getByRole('textbox', { name: 'Field for the password' }).fill(pw);
  await page.getByRole('textbox', { name: 'Field to confirm the password' }).fill(pw);
  await page.getByRole('combobox', { name: 'Selection list for the security question' }).click();
  await page.getByRole('option').first().click();
  await page.getByRole('textbox', { name: 'Field for the answer to the security question' }).fill('blue');
  await page.getByRole('button', { name: 'Button to complete the registration' }).click();
  await page.waitForURL(/#\/login/, { timeout: 10000 });
  await page.getByRole('textbox', { name: 'Text field for the login email' }).fill(email);
  await page.getByRole('textbox', { name: 'Text field for the login password' }).fill(pw);
  await page.getByRole('button', { name: 'Login', exact: true }).click();
  await page.waitForURL(/#\/search/, { timeout: 10000 });
  await page.goto('http://localhost:3000/#/payment/shop');
  await page.getByRole('button', { name: /Add new card/ }).click();
  out.push(await snap('card form'));
  await page.goto('http://localhost:3000/#/address/create');
  await page.getByRole('textbox', { name: 'Country' }).fill('Ukraine');
  await page.getByRole('textbox', { name: 'Name', exact: true }).fill('Test Customer');
  await page.getByRole('spinbutton', { name: 'Mobile Number' }).fill('501234567');
  await page.getByRole('textbox', { name: 'ZIP Code' }).fill('01001');
  await page.getByRole('textbox', { name: 'Address', exact: true }).fill('1 Khreshchatyk Street');
  await page.getByRole('textbox', { name: 'City' }).fill('Kyiv');
  await page.getByRole('textbox', { name: 'State' }).fill('Kyiv');
  await page.getByRole('button', { name: 'Submit' }).click();
  await page.waitForTimeout(1000);
  out.push(await snap('after address submit'));
  await page.goto('http://localhost:3000/#/address/select');
  out.push(await snap('address select'));
  return out.join('\n\n');
}

