import z85 from 'z85';

// Month names as the shop expects them in a coupon text: JAN, FEB, ...
const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

/**
 * Builds a coupon code: Z85 encoding of `<MMM><YY>-<NN>`.
 * `monthOffset` is relative to the current month of the machine: 0 is this month, -1 is the previous month.
 */
export function couponCode(monthOffset: number, discountPercent: number, now: Date = new Date()): string {
  const month = new Date(now.getFullYear(), now.getMonth() + monthOffset, 1);
  const mmm = MONTHS[month.getMonth()];
  const yy = String(month.getFullYear() % 100).padStart(2, '0');
  const nn = String(discountPercent).padStart(2, '0');
  return z85.encode(`${mmm}${yy}-${nn}`);
}

/** The 10% coupon of the current month. */
export const currentMonthCoupon = (): string => couponCode(0, 10);

/** The 10% coupon of the previous month: the shop must reject it. */
export const previousMonthCoupon = (): string => couponCode(-1, 10);

