// TC-02: Add a product to the basket (test-cases/TC-02-add-to-basket.md)
import { test, expect } from '../fixtures';
import { BasketPage } from '../pages/basket-page';
import { SearchPage } from '../pages/search-page';
import { PRODUCTS } from '../helpers/data';
import { newCustomer, registerAndLogin } from '../helpers/customer';

test('TC-02: add a product to the basket', async ({ page }) => {
  const product = PRODUCTS.eggfruitJuice;
  const search = new SearchPage(page);
  const basket = new BasketPage(page);
  await registerAndLogin(page, newCustomer('TC02'));

  await test.step('1. Open the product list: the product, its price and Add to Basket; basket counter 0', async () => {
    await search.goto();
    const card = search.product(product.name);
    await expect(card).toContainText(product.name);
    await expect(card).toContainText(product.price);
    await expect(card.getByRole('button', { name: 'Add to Basket' })).toBeVisible();
    await search.expectBasketCounter(0);
  });

  await test.step('2. Click Add to Basket: message and basket counter 1', async () => {
    await search.addToBasket(product.name);
    await search.expectNotification(`Placed ${product.name} into basket.`);
    await search.expectBasketCounter(1);
  });

  await test.step('3. Open the basket: one row with name, quantity 1 and price', async () => {
    await search.basketButton.click();
    await expect(page).toHaveURL(/#\/basket/);
    await basket.expectRow(product.name, 1);
    await expect(basket.row(product.name)).toContainText(product.price);
  });

  await test.step('4. The basket total is 8.99¤', async () => {
    await basket.expectTotal(product.price);
  });
});

