import { type Locator, type Page, expect } from '@playwright/test';

/** Top bar and account menu, shared by all shop pages. */
export class ShopPage {
  readonly accountButton: Locator;
  readonly basketButton: Locator;
  readonly menu: Locator;

  constructor(protected readonly page: Page) {
    this.accountButton = page.getByRole('button', { name: 'Show/hide account menu' });
    this.basketButton = page.getByRole('button', { name: 'Show the shopping cart' });
    this.menu = page.getByRole('menu');
  }

  async openAccountMenu(): Promise<void> {
    await this.accountButton.click();
    await expect(this.menu).toBeVisible();
  }

  async closeMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await expect(this.menu).toBeHidden();
  }

  /** Clicks an item of the open account menu, or of the sub menu that it opened. */
  async clickMenuItem(name: string): Promise<void> {
    await this.page.getByRole('menuitem', { name, exact: true }).click();
  }

  /** The notification (snack bar) that shows the given text. */
  notification(text: string): Locator {
    return this.page.locator('snack-bar-container, simple-snack-bar').filter({ hasText: text }).first();
  }

  async expectNotification(text: string): Promise<void> {
    await expect(this.notification(text)).toBeVisible();
  }

  /** The text of the basket button is "Your Basket <count>". */
  async expectBasketCounter(count: number): Promise<void> {
    await expect(this.basketButton).toHaveText(new RegExp(`^Your Basket\\s*${count}$`));
  }
}

