  await test.step('10. Order History shows one order with Total Price 8.99¤ and Bonus 1', async () => {
    await history.openAccountPage('Orders & Payment', 'Order History');
    const order = history.orderSection(orderId);
    await expect(order).toContainText('8.99¤');
    await expect(order).toContainText('Bonus');
