import { type Locator, type Page, expect } from '@playwright/test';
import { ShopPage } from './shop-page';

export class SearchPage extends ShopPage {
  constructor(page: Page) {
    super(page);
  }

  async goto(): Promise<void> {
    await this.page.goto('/#/search');
    await expect(this.page).toHaveURL(/#\/search/);
    await expect(this.page.locator('article').first()).toBeVisible();
  }

  product(name: string): Locator {
    return this.page.locator('article').filter({ hasText: name });
  }

  /**
   * Products are paged (15 per page), so a product may need the search query to show up.
   * Waits for the basket request, so that the next click does not race with this one.
   */
  async addToBasket(name: string): Promise<void> {
    if (!(await this.product(name).isVisible())) {
      await this.page.goto(`/#/search?q=${encodeURIComponent(name)}`);
    }
    await expect(this.product(name)).toBeVisible();
    const requested = this.page.waitForResponse(
      (r) => /\/api\/BasketItems/.test(r.url()) && r.request().method() === 'POST',
    );
    await this.product(name).getByRole('button', { name: 'Add to Basket' }).click();
    await requested;
  }
}

