import { randomUUID } from 'node:crypto';
import { type Page, expect } from '@playwright/test';
import { SAVED_ADDRESS, SAVED_CARD } from './data';

export type Customer = {
  email: string;
  password: string;
  wrongPassword: string;
};

/** A new customer with a unique email, as the test-cases README requires. */
export function newCustomer(testId: string): Customer {
  const tag = testId.toLowerCase();
  const password = `Passw0rd!${tag}`;
  return {
    email: `${tag}-${randomUUID().slice(0, 8)}@example.test`,
    password,
    wrongPassword: `${password}x`,
  };
}

/** Registers a normal customer account through the registration form. */
export async function registerCustomer(page: Page, customer: Customer): Promise<void> {
  await page.goto('/#/register');
  await page.getByRole('textbox', { name: 'Email address field' }).fill(customer.email);
  await page.getByRole('textbox', { name: 'Field for the password' }).fill(customer.password);
  await page.getByRole('textbox', { name: 'Field to confirm the password' }).fill(customer.password);
  // The question list loads from the API: retry the opening until an option is shown.
  const question = page.getByRole('combobox', { name: 'Selection list for the security question' });
  const firstOption = page.getByRole('option').first();
  await expect(async () => {
    await question.click();
    await expect(firstOption).toBeVisible({ timeout: 1000 });
  }).toPass();
  await firstOption.click();
  await page.getByRole('textbox', { name: 'Field for the answer to the security question' }).fill('blue');
  await page.getByRole('button', { name: 'Button to complete the registration' }).click();
  await expect(page).toHaveURL(/#\/login$/);
}

/** Logs in through the login form. Leaves the page on the product list. */
export async function loginCustomer(page: Page, customer: Customer): Promise<void> {
  await page.goto('/#/login');
  await page.getByRole('textbox', { name: 'Text field for the login email' }).fill(customer.email);
  await page.getByRole('textbox', { name: 'Text field for the login password' }).fill(customer.password);
  await page.getByRole('button', { name: 'Login', exact: true }).click();
  await expect(page).toHaveURL(/#\/search/);
}

/** Registers and logs in a new customer. */
export async function registerAndLogin(page: Page, customer: Customer): Promise<void> {
  await registerCustomer(page, customer);
  await loginCustomer(page, customer);
}

/** Saves the address from test-cases/README.md for the logged-in customer. */
export async function saveAddress(page: Page): Promise<void> {
  await page.goto('/#/address/create');
  await page.getByRole('textbox', { name: 'Country' }).fill(SAVED_ADDRESS.country);
  await page.getByRole('textbox', { name: 'Name', exact: true }).fill(SAVED_ADDRESS.name);
  await page.getByRole('spinbutton', { name: 'Mobile Number' }).fill(SAVED_ADDRESS.mobile);
  await page.getByRole('textbox', { name: 'ZIP Code' }).fill(SAVED_ADDRESS.zip);
  await page.getByRole('textbox', { name: 'Address', exact: true }).fill(SAVED_ADDRESS.address);
  await page.getByRole('textbox', { name: 'City' }).fill(SAVED_ADDRESS.city);
  await page.getByRole('textbox', { name: 'State' }).fill(SAVED_ADDRESS.state);
  const saved = page.waitForResponse(
    (r) => /\/api\/Addresss/.test(r.url()) && r.request().method() === 'POST' && r.ok(),
  );
  await page.getByRole('button', { name: 'Submit', exact: true }).click();
  await saved;
}

/** Saves the card from test-cases/README.md for the logged-in customer. */
export async function saveCard(page: Page): Promise<void> {
  await page.goto('/#/payment/shop');
  await page.getByRole('button', { name: /Add new card/ }).click();
  await page.getByRole('textbox', { name: 'Name', exact: true }).fill(SAVED_CARD.name);
  await page.getByRole('spinbutton', { name: 'Card Number' }).fill(SAVED_CARD.number);
  await page.getByRole('combobox', { name: 'Expiry Month' }).selectOption(SAVED_CARD.expiryMonth);
  await page.getByRole('combobox', { name: 'Expiry Year' }).selectOption(SAVED_CARD.expiryYear);
  const saved = page.waitForResponse(
    (r) => /\/api\/Cards/.test(r.url()) && r.request().method() === 'POST' && r.ok(),
  );
  await page.getByRole('button', { name: 'Submit', exact: true }).click();
  await saved;
}

/**
 * Adds money to the wallet through the shop API, with the saved card.
 * The wallet form only accepts 10 to 1000, but test-cases/TC-08 needs 5 and 3.99,
 * so the test setup uses the API. Returns the new wallet balance.
 */
export async function addWalletMoney(page: Page, amount: number): Promise<number> {
  return page.evaluate(async (value) => {
    const headers = {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${localStorage.getItem('token')}`,
    };
    const cards = await (await fetch('/api/Cards', { headers })).json();
    const paymentId = String(cards.data[0].id);
    const response = await fetch('/rest/wallet/balance', {
      method: 'PUT',
      headers,
      body: JSON.stringify({ paymentId, balance: value }),
    });
    if (!response.ok) {
      throw new Error(`Wallet top-up failed: HTTP ${response.status}`);
    }
    const balance = await (await fetch('/rest/wallet/balance', { headers })).json();
    return balance.data as number;
  }, amount);
}

