import { type Locator, type Page, expect } from '@playwright/test';
import { ShopPage } from './shop-page';

export class OrderHistoryPage extends ShopPage {
  async goto(): Promise<void> {
    await this.page.goto('/#/order-history');
    await expect(this.page.getByRole('heading', { name: 'Order History' })).toBeVisible();
  }

  /** The innermost block that holds the order ID and its total: the block of one order. */
  orderSection(orderId: string): Locator {
    return this.page
      .locator('div')
      .filter({ hasText: orderId })
      .filter({ hasText: 'Total Price' })
      .last();
  }
}

export class WalletPage extends ShopPage {
  async goto(): Promise<void> {
    await this.page.goto('/#/wallet');
    await expect(this.page.getByRole('heading', { name: 'Digital Wallet' })).toBeVisible();
  }

  /** The page shows "Wallet Balance <amount>" without the currency sign. */
  async expectBalance(balance: string): Promise<void> {
    await expect(this.page.locator('body')).toContainText(new RegExp(`Wallet Balance\\s*${balance.replace('.', '\\.')}`));
  }
}

